chapter(16, 'Linen, stock and purchasing', 'Issue towels to a floor, receive 50 soap bars from the vendor Sai Suppliers, and read the laundry, count, loss and consumption tabs. Money stays hidden from the supervisor.',
        'Neha (Supervisor)', 'supervisor', menu='Stock & Purchasing')
step('Neha, the housekeeping supervisor, is on Modules Home. Linen and supplies are in the Stock & Purchasing module.', 'Linen and amenities are the hotel\'s second biggest hidden cost, so every movement is written down.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:supervisor'], action='read', expect='Modules Home for Neha.', check="ctx.uid==='supervisor'")
tile('Stock & Purchasing', 'Click the Stock & Purchasing tile. The module has a single page, so the tile opens it directly.', 'Linen & stock is the screen of the store.', expect='The Linen & stock page opens.', check="ctx.page==='inventory'")
read('The Stock tab lists every item with its quantity in the store, on the floors and in the laundry, and the Reorder alerts for items below their minimum. Chips filter Linen, Amenities and Cleaning supplies. For Neha there are no prices.', 'The supervisor sees quantities, not money.', target='tab:Stock', expect='The stock list and the reorder alerts.')
click('btn:Issue / use', 'Click Issue / use. Floor 2 needs fresh towels.', 'Linen leaves the store only against a written issue.', expect='The Issue, return or use dialog opens.', check="has('Issue to floor')")
step('Choose the item Bath towel, the pantry of Floor 2 and the quantity 20.', 'The floor pantry is the stock of the attendants on that floor.', target='field:Quantity', auto=['select:field:Item|Bath towel', 'select:field:To floor pantry|Floor 2', 'type:field:Quantity|20'], action='select', expect='Bath towel, Floor 2 pantry, 20 pieces.')
click('lastbtn:Issue to floor', 'Click Issue to floor.', 'The store count goes down by 20 and the Floor 2 pantry count goes up.', expect='Twenty towels are issued to Floor 2.')
click('btn:Receive stock', 'Click Receive stock. A delivery of soap has arrived.', 'A goods received note, GRN, records what came in, from whom and on which bill.', expect='The Receive stock dialog opens.', check="has('Receive to store')")
step('Type the supplier Sai Suppliers and the delivery note SS-4471. Choose Soap bar 30 g and the quantity 50.', 'The supplier and the bill number let the accountant match the purchase invoice later.', target='field:Supplier', auto=['type:field:Supplier|Sai Suppliers', 'type:field:Delivery note|SS-4471', 'select:field:Item|Soap bar', 'type:field:Quantity|50'], action='type', expect='The GRN lines are filled.')
click('modalbtn:Receive to store', 'Click Receive to store.', 'The soap is in the store at once; the reorder alert for soap clears.', expect='The delivery is received.')
click('tab:Laundry', 'Open the Laundry tab.', 'Each batch of linen sent to the laundry is counted out and counted in again, so a shortage is seen on the day.', expect='The laundry batches are listed.')
click('tab:Counts', 'Open the Counts tab.', 'A physical count compares the shelf with the record; differences need a reviewer.', expect='The counts are listed with Review.')
click('tab:Losses', 'Open the Losses tab.', 'Damaged, lost and stained linen is written off here with a reason.', expect='The losses are listed.')
click('tab:Consumption', 'Open the Consumption tab.', 'Consumption per occupied room shows whether amenities are used or wasted.', expect='The consumption report opens.')
click('tab:Par', 'Open the Par & minimums tab.', 'Par is the quantity the hotel wants to hold; the minimum triggers the reorder alert.', expect='The par and minimum levels are listed.')
click('tab:Movements', 'Open the Movements tab.', 'Every issue, receipt and loss is a line here with the user and the time.', expect='The movements include the 20 towels and the 50 soap bars.')
read('Purchase bills, vendor payments and the asset register are kept by the accountant under Accounts & Reports, Accounting; chapter 21 shows them. The supervisor never sees what the soap cost.', 'Stock quantities belong to housekeeping, money belongs to the accounts.', target='tab:Movements', expect='The end of the stock chapter.')
